Script:
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$ErrorActionPreference = 'Stop'

Write-Host "AzureKeyVault secrets import starting"

Write-Host "Logging in to Azure Account"
$AzTenantId = $Jaws.Parameters["STEP.AzureAccount.TenantID"].Value
$AzSubscriptionId = $Jaws.Parameters["STEP.AzureAccount.SubscriptionID"].Value
$AzApplicationId = $Jaws.Parameters["STEP.AzureAccount.ApplicationID"].Value
$AzApplicationPassword = $Jaws.Parameters["STEP.AzureAccount.ApplicationPassword"].Value

if ([string]::IsNullOrWhiteSpace($AzTenantId)) {
  throw "Required parameter AzureAccount.TenantID not specified"
}
if ([string]::IsNullOrWhiteSpace($AzApplicationId)) {
  throw "Required parameter AzureAccount.ApplicationID not specified"
}
if ([string]::IsNullOrWhiteSpace($AzApplicationPassword)) {
  throw "Required parameter AzureAccount.ApplicationPassword not specified"
}

Set-JawsAzLogin -TenantId $AzTenantId -ApplicationId $AzApplicationId -Password $AzApplicationPassword -SubscriptionId $AzSubscriptionId

# Variables
$AzVaultModuleName = "Az.KeyVault"
$AzureKeyVaultName = $Jaws.Parameters["STEP.AzureAccount.VaultName"].Value

$VaultSecretNames = $Jaws.Parameters["STEP.Secrets.SecretsList"].Value
$PrintVariableNames = $Jaws.Parameters["STEP.Secrets.PrintOutVariableNames"].Value

$AzVaultModuleSpecificVersion = $Jaws.Parameters["STEP.AzureCustomSetup.CustomModuleVersion"].Value
$AzVaultModuleCustomInstallLocation = $Jaws.Parameters["STEP.AzureCustomSetup.CustomModuleLocation"].Value

# Validation
if ([string]::IsNullOrWhiteSpace($AzureKeyVaultName)) {
  throw "Required parameter AzureAccount.VaultName not specified"
}
if ([string]::IsNullOrWhiteSpace($VaultSecretNames)) {
  throw "Required parameter Secrets.SecretsList not specified"
}

# Cross-platform bits
$WindowsPowerShell = $True
if ($PSEdition -eq "Core") {
  $WindowsPowerShell = $False
}

function Get-Module-CrossPlatform {
  [CmdletBinding()]
  Param(
    [Parameter(Mandatory = $true, Position = 0)]
    [string] $Name
  )
  
  $module = Get-Module -Name $Name -ListAvailable
  if ($WindowsPowerShell -eq $True -and $null -eq $module) {
    $module = Get-InstalledModule -Name $Name
  }
  
  return $module
}

$PowerShellModuleName = $AzVaultModuleName

# Check for Custom install location
if ([string]::IsNullOrWhiteSpace($AzVaultModuleCustomInstallLocation) -eq $false) {
  if ((Test-Path $AzVaultModuleCustomInstallLocation -IsValid) -eq $false) {
    throw "The path specified at AzureCustomSetup.CustomModuleLocation is not valid, please use a relative or absolute path."
  }
  
  $AzVaultModulesFolder = [System.IO.Path]::GetFullPath($AzVaultModuleCustomInstallLocation)
  $LocalModules = (New-Item "$AzVaultModulesFolder" -ItemType Directory -Force).FullName
  $env:PSModulePath = $LocalModules + [System.IO.Path]::PathSeparator + $env:PSModulePath
  
  # Check to see if the module exists
  $LocalModulePath = "$LocalModules/$AzVaultModuleName"
  if ((Test-Path -Path $LocalModulePath) -eq $true) {
    # Use specific location
    $PowerShellModuleName = $LocalModulePath
  }
}

# Import module
if ([string]::IsNullOrWhiteSpace($AzVaultModuleSpecificVersion) -eq $true) {
  Write-Host "Importing module $PowerShellModuleName ..."
  Import-Module -Name $PowerShellModuleName
}
else {
  Write-Host "Importing module $PowerShellModuleName at required version $AzVaultModuleSpecificVersion ..."
  Import-Module -Name $PowerShellModuleName -RequiredVersion $AzVaultModuleSpecificVersion
}

# Check if Az.KeyVault module is imported correctly in current session
$azVaultModule = Get-Module-CrossPlatform -Name $AzVaultModuleName
if ($null -eq $azVaultModule) {
  throw "Cannot find the '$AzVaultModuleName' module on the machine."
}

$Secrets = @()
$VariablesCreated = 0
$StepName = $Jaws.CurrentStep.StepName

# Extract secret names+versions 
@($VaultSecretNames.Split("`n").Trim()) | ForEach-Object {
  if ([string]::IsNullOrWhiteSpace($_) -eq $false) {
    Write-Verbose "Working on: '$_'"
    $secretDefinition = $_.Split('|')
    $secretName = $secretDefinition[0].Trim()
    $secretNameAndVersion = $secretName.Split(" ")
    $secretVersion = $null
    if ($secretNameAndVersion.Count -gt 1) {
      $secretName = $secretNameAndVersion[0].Trim()
      $secretVersion = $secretNameAndVersion[1].Trim()
    }
    if ([string]::IsNullOrWhiteSpace($secretName) -eq $true) {
      throw "Unable to establish secret name from: '$($_)'"
    }
    $secret = [PsCustomObject]@{
      Name          = $secretName
      SecretVersion = $secretVersion
      VariableName  = if (![string]::IsNullOrWhiteSpace($secretDefinition[1])) { $secretDefinition[1].Trim() } else { "" }
    }
    $Secrets += $secret
  }
}

Write-Host "Vault Name: $AzureKeyVaultName"
Write-Host "Print variables: $PrintVariableNames"
Write-Host "Secrets to retrieve: $($Secrets.Count)"
Write-Host "$AzVaultModuleName module version specified: $AzVaultModuleSpecificVersion"
Write-Host "$AzVaultModuleName module custom installation directory: $AzVaultModuleCustomInstallLocation"

# Retrieve Secrets
foreach ($secret in $secrets) {
  $name = $secret.Name
  $secretVersion = $secret.SecretVersion
  $variableName = $secret.VariableName
  if ([string]::IsNullOrWhiteSpace($variableName)) {
    $variableName = "$($AzureKeyVaultName.Trim()).$($name.Trim())"
  }
  
  # Call to Azure!
    
  if ([string]::IsNullOrWhiteSpace($secretVersion)) {
    Write-Host "Fetching $name$ver from $AzureKeyVaultName"
    $azSecretValue = Get-AzKeyVaultSecret -VaultName $AzureKeyVaultName -Name $name -AsPlainText
  }
  else {
    Write-Host "Fetching $name @ $secretVersion from $AzureKeyVaultName"
    $azSecretValue = Get-AzKeyVaultSecret -VaultName $AzureKeyVaultName -Name $name -Version $secretVersion -AsPlainText
  }

  if ([string]::IsNullOrWhiteSpace($azSecretValue)) {
    $ver = $secretVersion ? " @ $secretVersion" : ""
    Write-Warning "Secret $name$ver not found in $AzureKeyVaultName - no output variable will be produced"
  } else {
    Set-JawsOutputValue -Name $variableName -Value $azSecretValue -Type Secret
    $VariablesCreated += 1
  }
}

Write-Host "Created $variablesCreated output variables"
Write-Host "AzureKeyVault secrets import complete"

Remove-JawsAzLogin
Write-Host "Logged off from Azure"
